/**
 * Every reference between two tenant tables, generated from the schema v14
 * foreign-key catalog (ADR 0008). Do not edit by hand: regenerate it from a
 * migrated database with the catalog query in
 * `tests/integration/workspace_isolation_postgres_test.ts`, which fails while
 * the live catalog and this list differ. A new reference therefore cannot land
 * without being listed here, with the kind whose negative cross-workspace test
 * covers it.
 *
 * Every entry is a composite `(workspace_id, column)` key onto the parent's
 * `(workspace_id, id)`, apart from `api_request_logs_member_id_fkey`: a
 * request log outlives its workspace, so its member key stays plain.
 */

export type WorkspaceReferenceKind =
  | "aggregate"
  | "file"
  | "member"
  | "person"
  | "vocabulary";

export interface WorkspaceReference {
  readonly child: string;
  readonly column: string;
  readonly constraint: string;
  readonly kind: WorkspaceReferenceKind;
  readonly onDelete: "cascade" | "no action" | "restrict" | "set null";
  readonly parent: string;
}

/** The one tenant reference that stays plain (ADR 0008 amendment). */
export const PLAIN_WORKSPACE_REFERENCE = "api_request_logs_member_id_fkey";

